const std = @import("std");
const expect = std.testing.expect;
const expectEqual = std.testing.expectEqual;
const expectEqualStrings = std.testing.expectEqualStrings;

const token = @import("token.zig");
const Token = token.Token;
const TokenType = token.TokenType;

pub const Lexer = struct {
    const Self = @This();

    input: []const u8,
    pos: usize,
    read_pos: usize,
    ch: u8,

    pub fn init(input: []const u8) Self {
        var lexer = Self{
            .input = input,
            .pos = 0,
            .read_pos = 0,
            .ch = 0,
        };
        lexer.readChar();
        return lexer;
    }

    pub fn nextToken(l: *Self) Token {
        var tok: Token = undefined;
        l.munchWhitespace();
        switch (l.ch) {
            '=' => {
                if (l.peekChar() == '=') {
                    tok = Token.init(.eq, "==");
                    l.readChar();
                } else {
                    tok = Token.init(.assign, "=");
                }
            },
            '+' => tok = Token.init(.plus, "+"),
            '-' => tok = Token.init(.minus, "-"),
            '*' => tok = Token.init(.asterisk, "*"),
            '/' => tok = Token.init(.slash, "/"),
            '>' => tok = Token.init(.gt, ">"),
            '<' => tok = Token.init(.lt, "<"),
            '!' => {
                if (l.peekChar() == '=') {
                    tok = Token.init(.not_eq, "!=");
                    l.readChar();
                } else {
                    tok = Token.init(.bang, "!");
                }
            },
            ',' => tok = Token.init(.comma, ","),
            ';' => tok = Token.init(.semicolon, ";"),
            '(' => tok = Token.init(.l_paren, "("),
            ')' => tok = Token.init(.r_paren, ")"),
            '{' => tok = Token.init(.l_brace, "{"),
            '}' => tok = Token.init(.r_brace, "}"),
            0 => tok = Token.init(.eof, ""),
            else => {
                if (isLetter(l.ch)) {
                    tok.literal = l.readWord();
                    tok.type = token.keywordOrIdent(tok.literal);
                    return tok;
                } else if (isDigit(l.ch)) {
                    tok = Token.init(.int, l.readInt());
                    return tok;
                } else {
                    tok = Token.init(.illegal, &[1]u8{l.ch});
                }
            },
        }
        l.readChar();
        return tok;
    }

    fn readChar(l: *Self) void {
        if (l.read_pos >= l.input.len) {
            l.ch = 0;
        } else {
            l.ch = l.input[l.read_pos];
        }

        l.pos = l.read_pos;
        l.read_pos += 1;
    }

    fn peekChar(l: *Self) u8 {
        if (l.read_pos >= l.input.len) {
            return 0;
        } else {
            return l.input[l.read_pos];
        }
    }

    /// Read an identifier or keyword
    fn readWord(l: *Self) []const u8 {
        const start_pos = l.pos;
        while (isLetter(l.ch)) {
            l.readChar();
        }
        return l.input[start_pos..l.pos];
    }

    /// Read an integer
    fn readInt(l: *Self) []const u8 {
        const start_pos = l.pos;
        while (isDigit(l.ch)) {
            l.readChar();
        }
        return l.input[start_pos..l.pos];
    }

    fn munchWhitespace(l: *Self) void {
        while (l.ch == ' ' or l.ch == '\t' or l.ch == '\n' or l.ch == '\r') {
            l.readChar();
        }
    }
};

test "Lexer.new" {
    const lex = Lexer.init("let foo = 80;");

    try expectEqual(Lexer{
        .input = "let foo = 80;",
        .pos = 0,
        .read_pos = 1,
        .ch = 'l',
    }, lex);
}

fn isLetter(ch: u8) bool {
    return ('a' <= ch and ch <= 'z') or ('A' <= ch and ch <= 'Z') or ch == '_';
}

fn isDigit(ch: u8) bool {
    return '0' <= ch and ch <= '9';
}

test "Lexer.readChar" {
    var lex = Lexer{
        .input = "let foo = 80;",
        .pos = 0,
        .read_pos = 0,
        .ch = 0,
    };

    lex.readChar();

    try expectEqual(Lexer{
        .input = "let foo = 80;",
        .pos = 0,
        .read_pos = 1,
        .ch = 'l',
    }, lex);
}

test "Lexer.munchWhitespace" {
    const input = "     return 7;";

    var lex = Lexer.init(input);
    lex.munchWhitespace();

    try expectEqual(Lexer{
        .input = input,
        .pos = 5,
        .read_pos = 6,
        .ch = 'r',
    }, lex);
}

