```zig zig/src/token.zig
const std = @import("std");
const expectEqual = std.testing.expectEqual;
const assert = std.debug.assert;

pub const Token = struct {
    const Self = @This();

    type: TokenType,
    literal: []const u8,

    pub fn init(comptime token_type: TokenType, literal: []const u8) Self {
        // assert(!std.mem.eql(u8, literal, ""));

        const predefined_literal = token_type.literal();
        if (predefined_literal) |lit| {
            assert(std.mem.eql(u8, literal, lit));
        }

        return Self{
            .type = token_type,
            .literal = literal,
        };
    }

    pub fn format(
        self: Self,
        comptime fmt: []const u8,
        options: std.fmt.FormatOptions,
        writer: anytype,
    ) !void {
        _ = fmt;
        _ = options;

        const t_type = switch (self.type) {
            .illegal => "illegal ",
            .eof => "EOF ",
            .ident => "ident   ",
            .int => "int     ",
            .assign => "assign  ",
            .plus => "plus    ",
            .minus => "minus   ",
            .asterisk => "asterisk",
            .slash => "slash  ",
            .bang => "bang    ",
            .gt => "gt      ",
            .lt => "lt      ",
            .eq => "eq      ",
            .not_eq => "not_eq  ",
            .comma => "comma   ",
            .semicolon => "semicolon",
            .l_paren => "l_paren",
            .r_paren => "r_paren ",
            .l_brace => "l_brace",
            .r_brace => "r_brace",
            .function => "function",
            .let => "let     ",
            ._true => "true    ",
            ._false => "false   ",
            ._if => "if      ",
            ._else => "else    ",
            ._return => "return  ",
        };

        try writer.print(
            "| {s}\t{c}{s}{c}",
            .{ t_type, '"', self.literal, '"' },
        );
    }
};

