    l_brace,
    r_brace,

    // Keywords
    function,
    let,
    _true,
    _false,
    _if,
    _else,
    _return,

    fn literal(self: Self) ?[]const u8 {
        const result = switch (self) {
            TokenType.eof => "",
            TokenType.assign => "=",
            TokenType.plus => "+",
            TokenType.minus => "-",
            TokenType.asterisk => "*",
            TokenType.slash => "/",
            TokenType.bang => "!",
